  1641	func pruneSemanticChildDirs(brainDir, rootRel, active string, cutoff time.Time) (int, error) {
  1642		if err := rejectExistingSymlinkPathComponents(brainDir, rootRel); err != nil {
  1643			return 0, err
  1644		}
  1645		root := filepath.Join(brainDir, rootRel)
  1646		entries, err := os.ReadDir(root)
  1647		if err != nil {
  1648			if os.IsNotExist(err) {
  1649				return 0, nil
  1650			}
  1651			return 0, err
  1652		}
  1653		pruned := 0
  1654		for _, entry := range entries {
  1655			if !entry.IsDir() {
  1656				continue
  1657			}
  1658			path := filepath.Join(root, entry.Name())
  1659			if active != "" && filepath.Clean(path) == active {
  1660				continue
  1661			}
  1662			if err := rejectSymlinkPathComponents(brainDir, filepath.Join(rootRel, entry.Name())); err != nil {
  1663				return 0, err
  1664			}
  1665			info, err := entry.Info()
  1666			if err != nil {
  1667				continue
  1668			}
  1669			if info.ModTime().Before(cutoff) {
  1670				if err := os.RemoveAll(path); err != nil {
  1671					return 0, err
  1672				}
  1673				pruned++
  1674			}
  1675		}
  1676		return pruned, nil
  1677	}
