  1682			days, err := strconv.Atoi(strings.TrimSuffix(value, "d"))
  1683			if err != nil || days < 0 {
  1684				return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
  1685			}
  1686			return now.Add(-time.Duration(days) * 24 * time.Hour), nil
  1687		}
  1688		duration, err := time.ParseDuration(value)
  1689		if err != nil {
  1690			return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
  1691		}
  1692		return now.Add(-duration), nil
  1693	}
