  1961	func rejectSymlinkPathComponents(root, rel string) error {
  1962		clean := filepath.Clean(rel)
  1963		if filepath.IsAbs(clean) || clean == "." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
  1964			return fmt.Errorf("path is outside root: %s", rel)
  1965		}
  1966		current := root
  1967		for _, part := range strings.Split(clean, string(filepath.Separator)) {
  1968			current = filepath.Join(current, part)
  1969			info, err := os.Lstat(current)
  1970			if err != nil {
  1971				return err
  1972			}
  1973			if info.Mode()&os.ModeSymlink != 0 {
  1974				return fmt.Errorf("path component must not be a symlink: %s", rel)
  1975			}
  1976		}
  1977		rootResolved, err := filepath.EvalSymlinks(root)
  1978		if err != nil {
  1979			return err
  1980		}
  1981		pathResolved, err := filepath.EvalSymlinks(filepath.Join(root, clean))
  1982		if err != nil {
  1983			return err
  1984		}
  1985		if !pathInside(rootResolved, pathResolved) {
  1986			return fmt.Errorf("path escapes root through symlinks: %s", rel)
  1987		}
  1988		return nil
  1989	}
