  2076	func resolvedOutputPath(output string) (string, error) {
  2077		if resolved, err := filepath.EvalSymlinks(output); err == nil {
  2078			return filepath.Abs(resolved)
  2079		}
  2080		absOutput, err := filepath.Abs(output)
  2081		if err != nil {
  2082			return "", err
  2083		}
  2084		volume := filepath.VolumeName(absOutput)
  2085		rest := strings.TrimPrefix(absOutput, volume)
  2086		parts := strings.Split(strings.Trim(rest, string(filepath.Separator)), string(filepath.Separator))
  2087		existing := volume + string(filepath.Separator)
  2088		var missing []string
  2089		for i, part := range parts {
  2090			candidate := filepath.Join(existing, part)
  2091			if _, err := os.Lstat(candidate); err != nil {
  2092				if os.IsNotExist(err) {
  2093					missing = parts[i:]
  2094					break
  2095				}
  2096				return "", err
  2097			}
  2098			existing = candidate
  2099		}
  2100		resolvedExisting, err := filepath.EvalSymlinks(existing)
  2101		if err != nil {
  2102			return "", err
  2103		}
  2104		for _, part := range missing {
  2105			resolvedExisting = filepath.Join(resolvedExisting, part)
  2106		}
  2107		return filepath.Abs(resolvedExisting)
  2108	}
