  2187			if err != nil {
  2188				return err
  2189			}
  2190			_, copyErr := io.CopyN(out, tr, header.Size)
  2191			closeErr := out.Close()
  2192			if copyErr != nil {
  2193				return copyErr
  2194			}
  2195			if closeErr != nil {
  2196				return closeErr
  2197			}
  2198		}
  2199		importManifest, err := validateImportedBundle(tmpDir, storage.Key)
  2200		if err != nil {
  2201			return err
  2202		}
  2203		if err := filepath.WalkDir(tmpDir, func(path string, d os.DirEntry, walkErr error) error {
  2204			if walkErr != nil {
  2205				return walkErr
  2206			}
  2207			if d.IsDir() {
